// Load config and booking from previous nodes
const config = $('Set Config').first().json.config;
const booking = $input.first().json.booking;

// Calculate end time if not provided
let requestedStart = new Date(booking.requested_start);
let requestedEnd;

if (booking.requested_end) {
  requestedEnd = new Date(booking.requested_end);
} else {
  requestedEnd = new Date(requestedStart.getTime() + config.appointmentDurationMinutes * 60 * 1000);
}

// Add buffers for availability check
const checkStart = new Date(requestedStart.getTime() - config.bufferBeforeMinutes * 60 * 1000);
const checkEnd = new Date(requestedEnd.getTime() + config.bufferAfterMinutes * 60 * 1000);

// Generate dedupe key
const dedupeKey = `${booking.email.toLowerCase()}_${requestedStart.toISOString()}_${booking.service_type}`.replace(/[^a-zA-Z0-9_-]/g, '_');

// Get day of week (0 = Sunday, 1 = Monday, etc.)
const dayOfWeek = requestedStart.getDay();

// Parse working hours for the requested day
const workingDays = config.workingDays || [1, 2, 3, 4, 5];
const workingHoursStart = config.workingHoursStart || '09:00';
const workingHoursEnd = config.workingHoursEnd || '17:00';

// Create date objects for working hours on the requested day
const [startHour, startMin] = workingHoursStart.split(':').map(Number);
const [endHour, endMin] = workingHoursEnd.split(':').map(Number);

const workDayStart = new Date(requestedStart);
workDayStart.setHours(startHour, startMin, 0, 0);

const workDayEnd = new Date(requestedStart);
workDayEnd.setHours(endHour, endMin, 0, 0);

// Calculate min and max booking times
const now = new Date();
const minBookingTime = new Date(now.getTime() + config.minNoticeHours * 60 * 60 * 1000);
const maxBookingTime = new Date(now.getTime() + config.maxDaysAhead * 24 * 60 * 60 * 1000);

// Validation checks
let validationErrors = [];

// Check if day is a working day
const isWorkingDay = config.allowWeekends ? true : workingDays.includes(dayOfWeek);
if (!isWorkingDay) {
  validationErrors.push('Selected day is not a working day');
}

// Check if within working hours
if (requestedStart < workDayStart || requestedEnd > workDayEnd) {
  validationErrors.push(`Appointment must be within working hours (${workingHoursStart} - ${workingHoursEnd})`);
}

// Check minimum notice
if (requestedStart < minBookingTime) {
  validationErrors.push(`Appointments require at least ${config.minNoticeHours} hours notice`);
}

// Check maximum days ahead
if (requestedStart > maxBookingTime) {
  validationErrors.push(`Appointments cannot be booked more than ${config.maxDaysAhead} days in advance`);
}

// Email validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(booking.email)) {
  validationErrors.push('Invalid email format');
}

return {
  json: {
    booking: {
      ...booking,
      requested_end: requestedEnd.toISOString(),
      dedupe_key: dedupeKey
    },
    validation: {
      isValid: validationErrors.length === 0,
      errors: validationErrors,
      checkStart: checkStart.toISOString(),
      checkEnd: checkEnd.toISOString(),
      dayOfWeek,
      isWorkingDay
    },
    config
  }
};

// Find alternative available slots
const config = $('Set Config').first().json.config;
const booking = $('Validate Booking Constraints').first().json.booking;
const existingEvents = $input.all().map(item => item.json);

// Get events from calendar (we need to re-query for a wider range)
const now = new Date();
const searchEndDate = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // Next 7 days

// Parse working hours
const [startHour, startMin] = config.workingHoursStart.split(':').map(Number);
const [endHour, endMin] = config.workingHoursEnd.split(':').map(Number);
const workingDays = config.workingDays || [1, 2, 3, 4, 5];
const duration = config.appointmentDurationMinutes;
const bufferBefore = config.bufferBeforeMinutes;
const bufferAfter = config.bufferAfterMinutes;
const totalSlotTime = duration + bufferBefore + bufferAfter;

// Build list of busy times from existing events
// Note: In a real scenario, we would need another calendar query here
// For now, we'll return suggested times based on working hours

let alternatives = [];
let checkDate = new Date(now.getTime() + config.minNoticeHours * 60 * 60 * 1000);

// Round up to next slot boundary
checkDate.setMinutes(Math.ceil(checkDate.getMinutes() / 30) * 30, 0, 0);

while (alternatives.length < 3 && checkDate < searchEndDate) {
  const dayOfWeek = checkDate.getDay();

  // Check if it's a working day
  if (workingDays.includes(dayOfWeek)) {
    // Set to start of working hours if before
    const workStart = new Date(checkDate);
    workStart.setHours(startHour, startMin, 0, 0);

    const workEnd = new Date(checkDate);
    workEnd.setHours(endHour, endMin, 0, 0);

    // Adjust checkDate if it's before work start
    if (checkDate < workStart) {
      checkDate = new Date(workStart);
    }

    // Check slots during working hours
    while (checkDate.getTime() + duration * 60 * 1000 <= workEnd.getTime() && alternatives.length < 3) {
      const slotEnd = new Date(checkDate.getTime() + duration * 60 * 1000);

      // Add to alternatives (in production, check against busy times)
      alternatives.push({
        start: checkDate.toISOString(),
        end: slotEnd.toISOString(),
        formatted: checkDate.toLocaleString('en-US', {
          weekday: 'long',
          month: 'long',
          day: 'numeric',
          hour: 'numeric',
          minute: '2-digit',
          timeZone: config.timezone
        })
      });

      // Move to next slot
      checkDate = new Date(checkDate.getTime() + totalSlotTime * 60 * 1000);
    }
  }

  // Move to next day
  checkDate.setDate(checkDate.getDate() + 1);
  checkDate.setHours(0, 0, 0, 0);
}

return {
  json: {
    conflict: true,
    message: 'The requested time slot is not available.',
    alternatives,
    booking,
    config
  }
};

// Generate HMAC token for reschedule/cancel links
const crypto = require('crypto');

const config = $('Set Config').first().json.config;
const booking = $('Validate Booking Constraints').first().json.booking;

// Token expires in 30 days
const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

// Create token payload
const payload = {
  appointment_id: booking.appointment_id,
  client_email: booking.email,
  expires_at: expiresAt
};

const payloadString = JSON.stringify(payload);
const payloadBase64 = Buffer.from(payloadString).toString('base64url');

// Create HMAC signature
const signature = crypto
  .createHmac('sha256', config.tokenSecret)
  .update(payloadBase64)
  .digest('base64url');

// Full token: base64url(payload).signature
const token = `${payloadBase64}.${signature}`;

// Generate URLs
const rescheduleUrl = `${config.webhookBaseUrl}/appointment-reschedule?token=${encodeURIComponent(token)}&action=reschedule`;
const cancelUrl = `${config.webhookBaseUrl}/appointment-reschedule?token=${encodeURIComponent(token)}&action=cancel`;

return {
  json: {
    booking: {
      ...booking,
      token,
      reschedule_url: rescheduleUrl,
      cancel_url: cancelUrl,
      token_expires_at: expiresAt
    },
    config
  }
};
